<?php
require_once __DIR__.'/../includes/bootstrap.php'; requireLogin();
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$title=trim($_POST['course_title']??'');$desc=trim($_POST['course_description']??'');$price=max(0,(int)($_POST['price_iqd']??0));$videos=max(0,(int)($_POST['videos_count']??0));
if($title===''||$desc===''||$videos<1){$error=t('course_info_error');} elseif(!isset($_FILES['course_zip'])||$_FILES['course_zip']['error']!==UPLOAD_ERR_OK){$error=t('zip_upload_error');} else {$f=$_FILES['course_zip'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if($ext!=='zip'){$error=t('zip_type_error');}elseif($f['size']>500*1024*1024){$error=t('zip_size_error');}else{$name='course_'.$_SESSION['user_id'].'_'.time().'.zip';$dir=__DIR__.'/../uploads/courses';if(!is_dir($dir))mkdir($dir,0775,true);move_uploaded_file($f['tmp_name'],$dir.'/'.$name);$st=$pdo->prepare("INSERT INTO course_submissions(user_id,course_title,course_description,price_iqd,videos_count,zip_path) VALUES(?,?,?,?,?,?)");$st->execute([$_SESSION['user_id'],$title,$desc,$price,$videos,'uploads/courses/'.$name]);$message=t('course_submitted');}}}
$pageTitle=t('teach_course');require __DIR__.'/../includes/header.php';?>
<section class="section"><div class="container" style="max-width:800px"><div class="card"><h1><?=t('teach_title')?></h1><p class="muted"><?=t('teach_intro')?></p><?php if($message):?><div class="card" style="border-left:4px solid #6d35cf"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="card" style="border-left:4px solid #c44;color:#a33"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="field"><label><?=t('course_title')?></label><input name="course_title" required></div><div class="field"><label><?=t('course_description')?></label><textarea name="course_description" rows="6" required></textarea></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:15px"><div class="field"><label><?=t('price_iqd')?></label><input type="number" name="price_iqd" min="0" step="1000" value="0" required></div><div class="field"><label><?=t('video_count')?></label><input type="number" name="videos_count" min="1" required></div></div><div class="field"><label><?=t('course_zip')?></label><input type="file" name="course_zip" accept=".zip" required><small class="muted"><?=t('zip_help')?></small></div><button class="btn" type="submit"><?=t('submit_course')?></button></form></div></div></section>
